param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1)
$ErrorActionPreference="Stop";function Session([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)};function Post([string]$path,[hashtable]$payload,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($payload|ConvertTo-Json -Depth 12 -Compress)}
$hq=Session hq;$agency=Session agency;$client=Session client;$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"};$stamp=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/content-proof"
$asset=Post "$root/assets" @{content_type="cases";content_reference="CASE-$stamp";display_name="Authorized case $stamp";source_reference="SOURCE-$stamp";authorization_reference="AUTH-$stamp";public_scope="global website"} $hh;$version=Post "$root/assets/$($asset.id)/versions" @{locale="en-US";content_manifest=@{title="Authorized factory case $stamp";summary="Verified delivery evidence"}} $hh;$version=Post "$root/versions/$($version.id)/verify" @{expected_revision=$version.revision;reference="PROOF-VERIFY-$stamp"} $ah;$publication=Post "$root/versions/$($version.id)/publications" @{target="website-case";rollback_reference="PROOF-ROLLBACK-$stamp"} $hh;$publication=Post "$root/publications/$($publication.id)/approve" @{expected_revision=$publication.revision;reference="PROOF-APPROVE-$stamp"} $ah;$publication=Post "$root/publications/$($publication.id)/acknowledge" @{expected_revision=$publication.revision;reference="PROOF-RECEIPT-$stamp"} $ch;$workspace=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh
[pscustomobject]@{project_id=$ProjectId;asset_number=$asset.asset_number;asset_status=$asset.status;version_number=$version.version_number;version_status=$version.status;publication_number=$publication.publication_number;publication_status=$publication.status;publication_available=$publication.available;availability=$workspace.availability.status;source_content_mutated_directly=$workspace.contract.source_content_mutated_directly;authorization_bypassed=$workspace.contract.authorization_bypassed;customer_personal_data_stored=$workspace.contract.customer_personal_data_stored;consumer_handoff_required=$workspace.contract.consumer_handoff_required;evidence_count=$workspace.evidence.Count;hq=$hq.user.id;agency=$agency.user.id;client=$client.user.id}|ConvertTo-Json
